var t=`1269-asopao-de-pollo`;var n=`world-1269`;var o=`PR`;var a=`central-america-caribbean`;var s=4;var r=51;var l={en:`Asopao de Pollo`,ua:`Асопао з куркою`};var c={en:`Asopao de Pollo is a dish from Puerto Rico featuring chicken thigh, yellow onion, red bell pepper, garlic. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Асопао з куркою, страва кухні країни Пуерто-Рико з такими основними складниками: куряче стегно, жовта цибуля, червоний солодкий перець, часник. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var d=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 10 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 10 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:10,i:[[`chicken-thigh`,720,`g`],[`olive-oil`,45,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 9 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 9 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:9,i:[[`yellow-onion`,170,`g`],[`red-bell-pepper`,170,`g`],[`garlic`,4,`clove`]]},{en:`Rinse the rice, add the listed water, stock, coconut milk and aromatics as specified, cover and cook gently for about 29 minutes until tender and the liquid absorbs.`,ua:`Промийте рис, додайте зазначені воду, бульйон, кокосове молоко та прянощі, накрийте й готуйте приблизно 29 хвилин до м’якості та поглинання рідини.`,t:[`rice-washing`,`absorption-cooking`],m:29,i:[[`white-rice`,380,`g`],[`chicken-stock`,1150,`ml`],[`tomato`,270,`g`],[`green-olives`,85,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`cilantro`,20,`g`]]}];var g={slug:t,id:n,country:`PR`,region:a,servings:4,minutes:51,title:l,text:c,steps:d};export{o as country,g as default,n as id,r as minutes,a as region,s as servings,t as slug,d as steps,c as text,l as title};